// Self-test entry (ON+D). R1 collects a bit for each failure: 1 IROM, 2 IRAM, 3 KBD, 4 ESD, 5 U_LB, 6 UART, 7 RAM1, 8 RAM2, 9 IRLB, 10 IRIO. TestSummary shows it at the end
// SelfTest: firmware/upper/80000-selftest.s:9
pub(crate) fn SelfTest(r: &mut Run) {
    let mut at = r.cpu.pc;
    loop {
        match at {
            0x80000..=0x80005 => {
                op!(r, at, 0x80000..0x80002, 4, r.cpu.zero(R::C, Field::A)); // C=0 A
                op!(r, at, 0x80002..0x80005, 5, r.cpu.scratch(ScratchOp::ToScratch, R::C, 1, Field::W)); // R1=C
                branch!(r, at, 0x8000C, 9, r.cpu.call(0x01BFF)); // GOSBVL ClrScrMn
            }
            // #8000C:
            0x8000C..=0x8000C => {
                branch!(r, at, 0x80012, 8, r.cpu.call(0x8150C)); // GOSUBL DrawGrid
            }
            // #80012:
            0x80012..=0x80012 => {
                branch!(r, at, 0x80019, 9, r.cpu.call(0x01C7F)); // GOSBVL D0->Sft1.L1
            }
            // #80019:
            0x80019..=0x80019 => {
                jump!(r, at, 6, r.cpu.pc = 0x8002B); // GOTO SelfTestWait
            }
            _ => {
                r.cpu.pc = at;
                return;
            }
        }
    }
}

