// C.P = nibble -> C.B = its hex digit in ASCII
// Nib>ASCII: firmware/upper/80000-selftest.s:204
pub(crate) fn Nib_ASCII(r: &mut Run) {
    let mut at = r.cpu.pc;
    loop {
        match at {
            0x80215..=0x80222 => {
                op!(r, at, 0x80215..0x80218, 5, r.cpu.zero(R::A, Field::B)); // A=0 B
                op!(r, at, 0x80218..0x8021B, 5, r.cpu.copy(R::A, R::C, Field::P)); // A=C P
                op!(r, at, 0x8021B..0x8021F, 6, r.cpu.load_const(R::C, 2, 0x39)); // LC(2) #39
                op!(r, at, 0x8021F..0x80222, 5, r.cpu.exch(R::C, R::A, Field::P)); // CAEX P
                branch!(r, at, 0x80227, 7, r.cpu.test(Test::Regs(Cmp::Le, R::C, R::A), Field::P, None)); // ?C<=A P / RTNYES
            }
            // #80227:
            0x80227..=0x80230 => {
                op!(r, at, 0x80227..0x8022A, 5, r.cpu.exch(R::C, R::A, Field::P)); // CAEX P
                op!(r, at, 0x8022A..0x8022D, 5, r.cpu.load_const(R::C, 1, 0x7)); // LC(1) #7
                op!(r, at, 0x8022D..0x80230, 5, r.cpu.add(R::C, R::A, Field::B)); // C=C+A B
                jump!(r, at, 9, r.cpu.rtn(RtnKind::Plain)); // RTN
            }
            _ => {
                r.cpu.pc = at;
                return;
            }
        }
    }
}

