// AB -> CD: copies the extended real in AB to CD; A and B are kept
// ABtoCD: firmware/upper/86FE4-lib0C0.s:676
pub(crate) fn ABtoCD(r: &mut Run) {
    let mut at = r.cpu.pc;
    loop {
        match at {
            0x87913..=0x8791C => {
                op!(r, at, 0x87913..0x87916, 5, r.cpu.copy(R::C, R::B, Field::W)); // C=B W
                op!(r, at, 0x87916..0x87919, 5, r.cpu.copy(R::D, R::C, Field::W)); // D=C W
                op!(r, at, 0x87919..0x8791C, 5, r.cpu.copy(R::C, R::A, Field::W)); // C=A W
                jump!(r, at, 9, r.cpu.rtn(RtnKind::Plain)); // RTN
            }
            _ => {
                r.cpu.pc = at;
                return;
            }
        }
    }
}

