                op!(r, at, 0x879BE..0x879C1, 5, r.cpu.scratch(ScratchOp::FromScratch, R::C, 4, Field::W)); // C=R4
                op!(r, at, 0x879C1..0x879C4, 5, r.cpu.d_from_r(1, R::C, false)); // D1=C
                op!(r, at, 0x879C4..0x879C7, 5, r.cpu.d_add(1, 12)); // D1=D1+ 12
                io!(r, at, 0x879C7..0x879CA, 19, r.cpu.load(1, R::C, Field::A, r.hw)); // C=DAT1 A
                op!(r, at, 0x879CA..0x879CD, 5, r.cpu.d_from_r(0, R::C, false)); // D0=C
                io!(r, at, 0x879CD..0x879D1, 30, r.cpu.store(0, R::A, Field::W, r.hw)); // DAT0=A W
                op!(r, at, 0x879D1..0x879D4, 5, r.cpu.d_add(0, 16)); // D0=D0+ 16
                op!(r, at, 0x879D4..0x879D7, 5, r.cpu.scratch(ScratchOp::FromScratch, R::A, 0, Field::W)); // A=R0
                io!(r, at, 0x879D7..0x879DB, 30, r.cpu.store(0, R::A, Field::W, r.hw)); // DAT0=A W
                op!(r, at, 0x879DB..0x879DE, 5, r.cpu.d_add(0, 16)); // D0=D0+ 16
