                io!(r, at, 0x879E8..0x879EB, 19, r.cpu.store(1, R::C, Field::A, r.hw)); // DAT1=C A
                op!(r, at, 0x879EB..0x879EE, 5, r.cpu.d_sub(1, 12)); // D1=D1- 12
                io!(r, at, 0x879EE..0x879F1, 19, r.cpu.load(1, R::C, Field::A, r.hw)); // C=DAT1 A
