                io!(r, at, 0x8C4E3..0x8C4E6, 19, r.cpu.load(1, R::A, Field::A, r.hw)); // A=DAT1 A
                op!(r, at, 0x8C4E6..0x8C4EC, 8, r.cpu.scratch(ScratchOp::ToScratch, R::A, 3, Field::A)); // R3=A.F A
