                op!(r, at, 0x8D779..0x8D77B, 4, r.cpu.add(R::D, R::C, Field::A)); // D=D+C A
                io!(r, at, 0x8D77B..0x8D77E, 19, r.cpu.load(0, R::A, Field::A, r.hw)); // A=DAT0 A
                op!(r, at, 0x8D77E..0x8D781, 5, r.cpu.d_add(0, 5)); // D0=D0+ 5
                jump_io!(r, at, 23, r.cpu.pc_indirect(R::A, r.hw)); // PC=(A)
